INSERT INTO school_logo_versions(school_id,version,bytes,sha256,width,height,source_url,source_note)
SELECT s.id,COALESCE(current.version,0)+1,decode('','base64'),'2baddae94eba4bfa59a0a62509de0c76c99bb865a131553af7fe55c1ed9d63a7',256,256,'https://www.ahau.edu.cn/static/img/logo123.png','Official university identity asset, visually reviewed 2026-11-21. Cropped complete emblem from official masthead; original artwork colors retained. Original SHA-256: 6ac7e78ba2a3e55c67073db25803c20c24374a912e86ad111d406a50ebc6661b'
FROM schools s LEFT JOIN LATERAL (SELECT version,sha256,source_url,source_note,actor_user_id FROM school_logo_versions v WHERE v.school_id=s.id ORDER BY version DESC LIMIT 1) current ON TRUE
WHERE s.slug='anhui-agricultural-university' AND s.status<>'archived' AND (current.version IS NULL)
ON CONFLICT(school_id,version) DO NOTHING;
--> statement-breakpoint
