FROM schools s LEFT JOIN LATERAL (SELECT version,sha256,source_url,source_note,actor_user_id FROM school_logo_versions v WHERE v.school_id=s.id ORDER BY version DESC LIMIT 1) current ON TRUE
WHERE s.slug='xiamen-university' AND s.status<>'archived' AND (current.version IS NULL OR (current.actor_user_id IS NULL AND current.sha256='8bcfb7e5a53eff2ab18d3e2638f087b9cfd9501115f41475fef14dceba11c258' AND current.source_url='https://commons.wikimedia.org/wiki/File:Xiamen_University_logo.svg' AND current.source_note='Existing preview asset migrated to school-managed storage. Source: https://en.wikipedia.org/wiki/Xiamen_University. Official-source verification remains pending; do not label as officially verified.'))
ON CONFLICT(school_id,version) DO NOTHING;
--> statement-breakpoint
